import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { CSSTransition, SwitchTransition } from "react-transition-group";
import { useRef, useEffect } from "react";
import Login from "./components/Login";
import Register from "./components/Register";
import Home from "./components/Home";
import Profile from "./components/Profile";
import { API_URL, getCurrentUser, refreshTokens } from "./api/auth";
import "./styles/App.css";

function AnimatedRoutes() {
    const location = useLocation();
    const nodeRef = useRef(null);

    return (
        <SwitchTransition mode="out-in">
            <CSSTransition
                key={location.pathname}
                nodeRef={nodeRef}
                timeout={400}
                classNames={
                    location.pathname === "/login"
                        ? "slide-right"
                        : location.pathname === "/register"
                            ? "slide-left"
                            : ""
                }
                unmountOnExit
            >
                <div ref={nodeRef}>
                    <Routes location={location}>
                        <Route path="/login" element={<Login />} />
                        <Route path="/register" element={<Register />} />
                        <Route path="/" element={<Home />} />
                        <Route path="/profile" element={<Profile />} />
                    </Routes>
                </div>
            </CSSTransition>
        </SwitchTransition>
    );
}

function RoleUpdateSubscriber() {
    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser?.id) return;

        const evtSource = new EventSource(`${API_URL}/sse/role-updates`);

        evtSource.onmessage = async (event) => {
            const updatedUserId = event.data; // предполагаем, что сервер присылает UUID пользователя
            console.log("Role update received for user:", updatedUserId);

            if (updatedUserId === currentUser.id) {
                console.log("Refreshing tokens for current user...");
                await refreshTokens();
                window.location.reload(); // либо обновить состояние React без перезагрузки
            }
        };

        evtSource.onerror = (err) => {
            console.error("SSE error", err);
            evtSource.close();
        };

        return () => evtSource.close();
    }, []);

    return null;
}

export default function App() {
    return (
        <Router>
            <RoleUpdateSubscriber />
            <AnimatedRoutes />
        </Router>
    );
}
